import{_ as a,o as t,c as s,a0 as n}from"./chunks/framework.bcCluOOn.js";const h=JSON.parse('{"title":"Standard Library","description":"","frontmatter":{},"headers":[],"relativePath":"specification/stdlib.md","filePath":"specification/stdlib.md"}'),i={name:"specification/stdlib.md"};function o(d,e,r,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="standard-library" tabindex="-1">Standard Library <a class="header-anchor" href="#standard-library" aria-label="Permalink to &quot;Standard Library&quot;">​</a></h1><p>AAYU is an opinionated language designed for building software platforms. Instead of forcing developers to download hundreds of third-party dependencies for standard application features, AAYU includes a robust Standard Library baked into the runtime.</p><p>Modules are imported using the <code>use</code> keyword.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use http.</span></span>
<span class="line"><span>use db.</span></span>
<span class="line"><span>use auth.</span></span></code></pre></div><h2 id="db-module" tabindex="-1"><code>db</code> Module <a class="header-anchor" href="#db-module" aria-label="Permalink to &quot;\`db\` Module&quot;">​</a></h2><p>Handles all database interactions. In AAYU, you rarely write raw SQL. The <code>db</code> module interacts directly with your declared <code>entity</code> definitions.</p><ul><li><code>create [Entity] with [Map]</code></li><li><code>find [Entity]</code></li><li><code>update [Entity] where [Condition] with [Map]</code></li><li><code>delete [Entity] where [Condition]</code></li></ul><p><em>(Note: These are syntax-level built-ins rather than traditional function calls to optimize the DX).</em></p><h2 id="http-module" tabindex="-1"><code>http</code> Module <a class="header-anchor" href="#http-module" aria-label="Permalink to &quot;\`http\` Module&quot;">​</a></h2><p>Handles web server routing and requests.</p><h3 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to &quot;Routing&quot;">​</a></h3><p>Routes map URL paths to AAYU tasks.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get &quot;/api/users&quot; to fetch_users.</span></span>
<span class="line"><span>post &quot;/api/users&quot; to create_user.</span></span></code></pre></div><h3 id="request-context" tabindex="-1">Request Context <a class="header-anchor" href="#request-context" aria-label="Permalink to &quot;Request Context&quot;">​</a></h3><p>The <code>http</code> module automatically injects context into route handler tasks.</p><ul><li><code>form &quot;field&quot; from req</code>: Extracts form data.</li><li><code>path &quot;id&quot; from req</code>: Extracts URL path parameters.</li><li><code>json req</code>: Parses the request body as a JSON map.</li></ul><h3 id="server-lifecycle" tabindex="-1">Server Lifecycle <a class="header-anchor" href="#server-lifecycle" aria-label="Permalink to &quot;Server Lifecycle&quot;">​</a></h3><ul><li><code>serve on [Port]</code>: Starts the HTTP server.</li></ul><h2 id="auth-and-rbac-modules" tabindex="-1"><code>auth</code> and <code>rbac</code> Modules <a class="header-anchor" href="#auth-and-rbac-modules" aria-label="Permalink to &quot;\`auth\` and \`rbac\` Modules&quot;">​</a></h2><p>Handle identity and access control natively.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use rbac.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>role Admin.</span></span>
<span class="line"><span>role Manager.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>allow Admin create User.</span></span>
<span class="line"><span>allow Manager update Document.</span></span></code></pre></div><h2 id="future-extensions" tabindex="-1">Future Extensions <a class="header-anchor" href="#future-extensions" aria-label="Permalink to &quot;Future Extensions&quot;">​</a></h2><p>The AAYU Standard Library is designed to expand based on the Intent Engine ecosystem. Future built-in modules will include:</p><ul><li><strong><code>vision</code></strong>: Native image processing and AI OCR.</li><li><strong><code>dataframe</code></strong>: Native data manipulation (pandas-equivalent).</li><li><strong><code>rag</code></strong>: Built-in vector database and Retrieval-Augmented Generation capabilities.</li></ul>`,24)])])}const b=a(i,[["render",o]]);export{h as __pageData,b as default};
